declare
  uid uuid := auth.uid();
  v_need_id uuid;
  v_agr public.agreements%rowtype;
  v_covered integer;
  v_need public.needs%rowtype;
  v_reason_kept boolean := false;
begin
  if uid is null then raise exception 'AUTH_REQUIRED' using errcode = '28000'; end if;
  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'REASON_REQUIRED' using errcode = 'P0001';
  end if;

  -- Discover without locking, authorize, then use the canonical lock order
  -- Need -> Agreement -> Response shared with selection/cancel/withdraw.
  select a.need_id into v_need_id
    from public.agreements a
   where a.id = p_agreement_id;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if not public.fn_is_party(p_agreement_id, uid) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;

  select * into v_need
    from public.needs n
   where n.id = v_need_id
   for update;
  if not found then raise exception 'NEED_NOT_FOUND' using errcode = 'P0002'; end if;

  select * into v_agr from public.agreements
   where id = p_agreement_id for update;
  if not found then raise exception 'AGREEMENT_NOT_FOUND' using errcode = 'P0002'; end if;
  if v_agr.need_id is distinct from v_need.id then
    raise exception 'AGREEMENT_NEED_MISMATCH' using errcode = 'P0001';
  end if;
  if not public.fn_is_party(p_agreement_id, uid) then
    raise exception 'NOT_PARTY' using errcode = '42501';
  end if;
  if v_agr.status = 'CANCELLED' then return; end if;
  if v_agr.status = 'COMPLETED' then
    raise exception 'ALREADY_COMPLETED' using errcode = 'P0001';
  end if;
  -- PKG-031a (deep read 7.16): once the worker has said the work is done, the requester confirms completion or
  -- reports a problem. Cancelling would take the finished job, and its rating, from the worker.
  if uid = v_agr.requester_account_id and exists (select 1 from public.agreement_execution x
       where x.agreement_id = v_agr.id and x.state = 'AWAITING_REQUESTER') then
    raise exception 'AGREEMENT_WORK_REPORTED_DONE' using errcode = 'P0001';
  end if;

  -- PKG-032a (deep read 7.15): the reason the app requires is kept where the other party and support read it, as
  -- the canceller's own message in the Agreement's conversation, the way rpc_report_problem keeps a problem.
  if not private.safety_pair_blocked(v_agr.requester_account_id, v_agr.worker_account_id)
     and not private.closure_account_restricted(v_agr.requester_account_id)
     and not private.closure_account_restricted(v_agr.worker_account_id) then
    insert into public.agreement_messages(agreement_id, agreement_version, sender_account_id, body)
    values (v_agr.id, v_agr.current_version, uid, left('Otkazujem Dogovor. Razlog: ' || btrim(p_reason), 2000));
    v_reason_kept := true;
  end if;

  update public.agreements set status = 'CANCELLED' where id = p_agreement_id;
  update public.agreement_execution set state = 'CANCELLED'
   where agreement_id = p_agreement_id;
  update public.need_selections set status = 'CANCELLED'
   where id = v_agr.selection_id;
  update public.marketplace_responses
     set status = 'NOT_SELECTED', selected_at = null
   where id = v_agr.selected_response_id;
  update public.access_grants
     set status = 'REVOKED',
         revoked_at = coalesce(revoked_at, statement_timestamp())
   where agreement_id = p_agreement_id and status = 'GRANTED';
  update public.notification_deliveries d
     set state = 'EXPIRED'
    from public.user_activity_events e
   where d.event_id = e.id
     and e.entity_type = 'AGREEMENT'
     and e.entity_id = p_agreement_id
     and d.state in ('CREATED','QUEUED','FAILED_RETRYABLE');

  v_covered := public.fn_need_covered_slots(v_agr.need_id);

  if v_covered < v_need.required_slots
     and v_need.status in ('ACTIVE','SELECTION')
     and not private.closure_account_restricted(v_need.requester_account_id) then
    -- Coverage truth changes even when search authority says do not search.
    perform set_config('uskoci.need_lifecycle', 'CANCEL_AGREEMENT', true);
    update public.needs set status = 'SELECTION' where id = v_need.id;

    -- Human search authority is independent from coverage. Cancellation never clears it.
    -- Time authority is also independent: no matching is reanimated after the admitted window.
    if v_need.remaining_search_closed_at is null
       and private.need_search_time_admitted_v1(v_need.id, clock_timestamp()) then
      perform private.enqueue_dispatch(v_need.id, clock_timestamp());
    else
      -- The existing Need status trigger blindly enqueues ACTIVE -> SELECTION.
      -- Remove that stale queue row when search/time authority says matching is closed.
      delete from private.dispatch_schedule where need_id = v_need.id;
    end if;
  end if;
  perform private.emit_event(
    case when uid=v_agr.requester_account_id then v_agr.worker_account_id else v_agr.requester_account_id end,
    case when uid=v_agr.requester_account_id then 'WORKER' else 'REQUESTER' end,
    'AGREEMENT_CANCELLED','AGREEMENT',v_agr.id,v_agr.current_version,
    'Dogovor je otkazan',
    case when v_reason_kept then 'Druga strana je otkazala Dogovor. Razlog je u Porukama.'
         else 'Druga strana je otkazala Dogovor.' end,
    'agreement-cancelled:'||v_agr.id::text,'NORMAL',
    jsonb_build_object('agreementId',v_agr.id,'state','CANCELLED'),null);
end;

declare
  v_event_id uuid;
  v_prefs public.notification_preferences%rowtype;
  v_cat text := private.category_of_event(p_event_type);
  v_cat_on boolean;
  v_quiet boolean;
  v_prio text := case when p_urgency = 'HITNO' then 'HIGH' else 'NORMAL' end;
  v_suppress text;
begin
  -- PKG-027c: every stored text addresses the person as "ti" and uses the product's words. Two emitting
  -- functions are trigger functions inside the certified closure source, so the texts are mapped here.
  p_title := private.notification_copy_v5(p_title);
  p_body := private.notification_copy_v5(p_body);
  -- 1) durable event, idempotentno
  insert into public.user_activity_events
    (recipient_user_id, recipient_role, event_type, entity_type, entity_id,
     entity_version, urgency, payload, dedupe_key)
  values (p_recipient, p_role, p_event_type, p_entity_type, p_entity_id,
     p_entity_version, p_urgency, p_payload, p_dedupe_key)
  on conflict (dedupe_key) do nothing
  returning id into v_event_id;

  if v_event_id is null then
    return null;  -- vec emitovano; nista se ne duplira
  end if;

  -- 2) preference; ako red ne postoji, vaze podrazumevane vrednosti
  select * into v_prefs from public.notification_preferences
   where user_id = p_recipient and role_context = p_role;
  if not found then
    v_prefs.in_app_enabled := true;
    -- PKG-029a (deep read 4.1): a role without its own row takes the push choice of the account's other role.
    -- A person who switched push on once expects it on; it was off for every event of the other role.
    v_prefs.push_enabled := coalesce((select np.push_enabled from public.notification_preferences np
                                       where np.user_id = p_recipient order by np.role_context limit 1), false);
    v_prefs.quiet_hours_enabled := false;
    v_prefs.urgent_overrides_quiet_hours := false;
    v_prefs.opportunities_enabled := true; v_prefs.responses_enabled := true;
    v_prefs.dogovor_enabled := true; v_prefs.execution_enabled := true;
    v_prefs.recovery_enabled := true; v_prefs.account_enabled := true;
  end if;

  v_cat_on := case v_cat
    when 'opportunities' then v_prefs.opportunities_enabled
    when 'responses'     then v_prefs.responses_enabled
    when 'dogovor'       then v_prefs.dogovor_enabled
    when 'execution'     then v_prefs.execution_enabled
    when 'recovery'      then v_prefs.recovery_enabled
    else v_prefs.account_enabled end;

  -- 3) IN_APP
  insert into public.notification_deliveries
    (event_id, recipient_user_id, recipient_role, channel, priority, state,
     suppression_reason, title, body, dedupe_key, expires_at)
  values (v_event_id, p_recipient, p_role, 'IN_APP', v_prio,
     case when v_prefs.in_app_enabled and v_cat_on then 'CREATED' else 'SUPPRESSED' end,
     case when v_prefs.in_app_enabled and v_cat_on then null
          when not v_cat_on then 'CATEGORY_OFF' else 'IN_APP_OFF' end,
     p_title, p_body, p_dedupe_key || ':in_app', p_expires_at)
  on conflict (dedupe_key) do nothing;

  -- 4) PUSH — tihi sati se postuju osim uz izricit opt-in za HITNO
  v_quiet := private.in_quiet_hours(v_prefs);
  v_suppress := case
    when not v_prefs.push_enabled then 'PUSH_OFF'
    when not v_cat_on then 'CATEGORY_OFF'
    when v_quiet and not (p_urgency = 'HITNO' and v_prefs.urgent_overrides_quiet_hours)
      then 'QUIET_HOURS'
    else null end;

  insert into public.notification_deliveries
    (event_id, recipient_user_id, recipient_role, channel, priority, state,
     suppression_reason, title, body, dedupe_key, expires_at)
  values (v_event_id, p_recipient, p_role, 'PUSH', v_prio,
     case when v_suppress is null then 'CREATED' else 'SUPPRESSED' end,
     v_suppress, p_title, p_body, p_dedupe_key || ':push', p_expires_at)
  on conflict (dedupe_key) do nothing;

  return v_event_id;
end;

begin
 if auth.role()='service_role' then
  if TG_OP in ('UPDATE','DELETE') and private.closure_redaction_allowed_v5(TG_RELID,TG_OP,to_jsonb(OLD),case when TG_OP='UPDATE' then to_jsonb(NEW) else null end) then
   if TG_OP='DELETE' then return OLD;end if;return NEW;
  end if;
 end if;

  new.updated_at := statement_timestamp();
  return new;
end;
